// =========================================================================
// 🧭 ROUTE, CLASSIFY & PARSE INCOMING TELEGRAM EVENT
// =========================================================================
const input = $input.first()?.json || {};
const DEFAULT_CHAT_ID = "1519369571"; // Serhat Kumas default Telegram Chat ID

// =========================================================================
// ⚙️ CENTRALIZED USER CONFIGURATION
// =========================================================================
const CONFIG = {
  // 📊 Google Sheets Document ID (from URL: /spreadsheets/d/<ID>/edit)
  spreadsheetId: "1RfUaHs0S3oYUKWkxjaUpXn8IM3gHcdpL097bS8q8vTM",

  // 📑 Target sheet tab name for expenses
  sheetName: "Expenses",

  // 📁 Parent Google Drive Folder ID for "Expenses" archive
  expensesParentFolderId: "1_vaeg2-25K0fowlTXxCixcANYBNoNQmj",

  // 💶 Default currency when symbol is ambiguous
  defaultCurrency: "EUR",
  defaultCurrencySymbol: "€",

  // ⏰ Timezone
  timezone: "Europe/Berlin"
};

// Access workflow persistent static memory for deduplication
const staticData = $getWorkflowStaticData("global");
staticData.processedUpdates = staticData.processedUpdates || {};
staticData.monthlyFolders = staticData.monthlyFolders || {};

// Clean up processed update IDs older than 3 minutes
const nowMs = Date.now();
for (const [key, timestamp] of Object.entries(staticData.processedUpdates)) {
  if (nowMs - timestamp > 180000) {
    delete staticData.processedUpdates[key];
  }
}

const msg = input.message || input.msg || input;
const chatId = String(msg.chat?.id || msg.from?.id || DEFAULT_CHAT_ID);
const messageId = msg.message_id || input.message_id;
const updateId = input.update_id || (messageId ? (chatId + "_" + messageId) : null);

// Deduplication Guard: Ignore if exact same update was already processed
if (updateId) {
  const uKey = "upd_" + updateId;
  if (staticData.processedUpdates[uKey]) {
    return [{ json: { eventType: "ignored", reason: "duplicate_update", chatId } }];
  }
  staticData.processedUpdates[uKey] = nowMs;
}

// Current date and time context in Europe/Berlin
const now = new Date();
const todayIso = now.toISOString().split("T")[0]; // YYYY-MM-DD
const currentYear = now.getFullYear();
const currentMonthNum = String(now.getMonth() + 1).padStart(2, "0");
const currentMonth = currentYear + "-" + currentMonthNum; // "2026-11"

const monthNames = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];
const currentMonthName = monthNames[now.getMonth()] + " " + currentYear;
const monthFolder = currentMonth + " (" + monthNames[now.getMonth()] + ")";

// 1. Detect Photo or Document Image Receipt
const photos = msg.photo;
const doc = msg.document;
let isImage = false;
let fileId = null;
let imageMimeType = "image/jpeg";

if (Array.isArray(photos) && photos.length > 0) {
  isImage = true;
  // Highest resolution photo is the last item in Telegram photo array
  const bestPhoto = photos[photos.length - 1];
  fileId = bestPhoto.file_id;
  imageMimeType = "image/jpeg";
} else if (doc && (doc.mime_type?.startsWith("image/") || /\.(jpe?g|png|webp|heic)$/i.test(doc.file_name || ""))) {
  isImage = true;
  fileId = doc.file_id;
  imageMimeType = doc.mime_type || "image/jpeg";
}

const caption = String(msg.caption || "").trim();
const rawText = String(msg.text || caption || "").trim();

// 2. Classify Event Type
if (isImage) {
  return [{
    json: {
      eventType: "receipt_photo",
      fileId,
      imageMimeType,
      caption,
      chatId,
      messageId,
      todayIso,
      currentMonth,
      currentMonthName,
      monthFolder,
      config: CONFIG
    }
  }];
}

// Check for Help / Start command
const lowerText = rawText.toLowerCase();
if (lowerText === "/start" || lowerText === "/help" || lowerText === "help" || lowerText === "yardım") {
  return [{
    json: {
      eventType: "help",
      chatId,
      messageId,
      config: CONFIG
    }
  }];
}

// Check for Spending Query vs Text Expense
const queryTriggers = [
  "how much", "spend", "spent", "spending", "total", "breakdown", "status", "summary",
  "report", "analysis", "budget", "cost", "expensive", "show me", "list",
  "harcadım", "harcama", "harcamalar", "ne kadar", "toplam", "durum", "özet",
  "rapor", "analiz", "bütçe", "göster", "kaç para", "masraf",
  "january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december",
  "ocak", "şubat", "mart", "nisan", "mayıs", "haziran", "temmuz", "ağustos", "eylül", "ekim", "kasım", "aralık",
  "this month", "last month", "bu ay", "geçen ay"
];

const isQuery = queryTriggers.some(trigger => lowerText.includes(trigger)) || lowerText.endsWith("?");

if (isQuery && rawText.length > 0) {
  return [{
    json: {
      eventType: "expense_query",
      rawText,
      chatId,
      messageId,
      todayIso,
      currentMonth,
      currentMonthName,
      config: CONFIG
    }
  }];
}

if (rawText.length > 0) {
  return [{
    json: {
      eventType: "receipt_text",
      rawText,
      chatId,
      messageId,
      todayIso,
      currentMonth,
      currentMonthName,
      config: CONFIG
    }
  }];
}

return [{
  json: {
    eventType: "ignored",
    chatId,
    reason: "empty_or_unsupported_update"
  }
}];

// =========================================================================
// 🖼️ PREPARE IMAGE BUFFER FOR GEMINI VISION & GOOGLE DRIVE
// =========================================================================
const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary?.data) {
    throw new Error('No receipt image binary found in "data". Telegram download may have failed.');
  }

  // Read binary data using n8n's storage-aware helper
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  if (!buffer.length) {
    throw new Error('Downloaded receipt image buffer is empty. Please resend the photo.');
  }

  const routeMeta = $('Route & Classify Input').first().json;
  const mimeType = item.binary.data.mimeType || routeMeta.imageMimeType || 'image/jpeg';
  const timeStamp = new Date().toISOString().replace(/[:.]/g, '-');
  const tempFileName = "Receipt_" + routeMeta.todayIso + "_" + timeStamp + ".jpg";

  output.push({
    json: {
      ...routeMeta,
      imageMimeType: mimeType,
      imageBase64: buffer.toString('base64'),
      tempFileName,
      timestamp: new Date().toISOString()
    },
    binary: {
      data: item.binary.data
    },
    pairedItem: { item: i }
  });
}

return output;

// =========================================================================
// 🔗 MERGE GEMINI VISION EXTRACTION & GOOGLE DRIVE LINK
// =========================================================================
const visionResp = $input.first()?.json || $('Gemini Vision: Extract Receipt Details').first()?.json || {};
const meta = $('Prepare Image Buffer').first().json;

let driveResp = {};
try {
  driveResp = $('Upload Receipt to Google Drive').first()?.json || {};
} catch (e) {
  driveResp = {};
}

let parsed = {};
try {
  const rawText = visionResp.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    isReceipt: true,
    merchant: 'Unknown Store',
    date: meta.todayIso,
    totalAmount: 0.0,
    currency: meta.config.defaultCurrency,
    currencySymbol: meta.config.defaultCurrencySymbol,
    category: 'General & Miscellaneous',
    itemsSummary: meta.caption || 'Receipt photo'
  };
}

// Drive link to preview uploaded receipt photo
const driveLink = driveResp.webViewLink || driveResp.webContentLink || 
  (driveResp.id ? ("https://drive.google.com/file/d/" + driveResp.id + "/view") : "N/A");

const totalAmount = parseFloat(parsed.totalAmount) || 0.0;
const dateStr = parsed.date || meta.todayIso;
const monthStr = dateStr.slice(0, 7);

return [{
  json: {
    chatId: meta.chatId,
    messageId: meta.messageId,
    isReceipt: parsed.isReceipt !== false,
    merchant: parsed.merchant || 'Unknown Merchant',
    date: dateStr,
    month: monthStr,
    totalAmount,
    currency: parsed.currency || meta.config.defaultCurrency,
    currencySymbol: parsed.currencySymbol || meta.config.defaultCurrencySymbol,
    category: parsed.category || 'General & Miscellaneous',
    itemsSummary: parsed.itemsSummary || meta.caption || 'Receipt item',
    paymentMethod: parsed.paymentMethod || 'Unknown',
    driveLink,
    driveFileId: driveResp.id || null,
    source: 'photo',
    config: meta.config
  }
}];

// =========================================================================
// 📝 PARSE TEXT EXPENSE OUTPUT
// =========================================================================
const resp = $input.first()?.json || {};
const meta = $('Route & Classify Input').first().json;

let parsed = {};
try {
  const rawText = resp.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    merchant: 'Manual Expense',
    date: meta.todayIso,
    totalAmount: 0.0,
    currency: meta.config.defaultCurrency,
    currencySymbol: meta.config.defaultCurrencySymbol,
    category: 'General & Miscellaneous',
    itemsSummary: meta.rawText
  };
}

const totalAmount = parseFloat(parsed.totalAmount) || 0.0;
const dateStr = parsed.date || meta.todayIso;
const monthStr = dateStr.slice(0, 7);

return [{
  json: {
    chatId: meta.chatId,
    messageId: meta.messageId,
    isReceipt: true,
    merchant: parsed.merchant || 'Manual Store',
    date: dateStr,
    month: monthStr,
    totalAmount,
    currency: parsed.currency || meta.config.defaultCurrency,
    currencySymbol: parsed.currencySymbol || meta.config.defaultCurrencySymbol,
    category: parsed.category || 'General & Miscellaneous',
    itemsSummary: parsed.itemsSummary || meta.rawText,
    paymentMethod: parsed.paymentMethod || 'Manual Entry',
    driveLink: 'N/A (Text Entry)',
    driveFileId: null,
    source: 'text',
    config: meta.config
  }
}];

// =========================================================================
// 📊 PREPARE GOOGLE SHEETS EXPENSE ROW
// =========================================================================
const item = $input.first().json;
const config = item.config || {};

const dateStr = item.date || new Date().toISOString().split('T')[0];
const monthStr = item.month || dateStr.slice(0, 7);

// Standardized row mapping matching the Google Sheets Expense Tracker
const sheetRow = {
  Date: dateStr,
  Month: monthStr,
  Merchant: item.merchant || 'Unknown Merchant',
  Category: item.category || 'General & Miscellaneous',
  Amount: item.totalAmount || 0,
  Currency: item.currency || 'EUR',
  'Receipt Drive Link': item.driveLink || 'N/A',
  'Items / Notes': item.itemsSummary || '',
  'Logged At': new Date().toISOString().replace('T', ' ').slice(0, 19)
};

return [{
  json: {
    ...item,
    ...sheetRow,
    spreadsheetId: config.spreadsheetId,
    sheetName: config.sheetName || 'Expenses'
  }
}];

