// =========================================================================
// 🔍 PARSE SPENDING QUERY TARGET PERIOD & INTENT
// =========================================================================
const item = $input.first().json;
const rawText = String(item.rawText || '').trim();
const lower = rawText.toLowerCase();
const now = new Date();
const currentYear = now.getFullYear();
const currentMonthNum = now.getMonth() + 1; // 1-12

// Month lookup dictionaries in English and Turkish
const monthsMap = {
  // English
  january: 1, jan: 1,
  february: 2, feb: 2,
  march: 3, mar: 3,
  april: 4, apr: 4,
  may: 5,
  june: 6, jun: 6,
  july: 7, jul: 7,
  august: 8, aug: 8,
  september: 9, sep: 9, sept: 9,
  october: 10, oct: 10,
  november: 11, nov: 11,
  december: 12, dec: 12,
  // Turkish
  ocak: 1, oca: 1,
  subat: 2, şubat: 2, sub: 2, şub: 2,
  mart: 3, mar: 3,
  nisan: 4, nis: 4,
  mayis: 5, mayıs: 5,
  haziran: 6, haz: 6,
  temmuz: 7, tem: 7,
  agustos: 8, ağustos: 8, agu: 8, ağu: 8,
  eylul: 9, eylül: 9, eyl: 9,
  ekim: 10, eki: 10,
  kasim: 11, kasım: 11, kas: 11,
  aralik: 12, aralık: 12, ara: 12
};

const monthNamesEn = [
  "", "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

let targetMonth = null;
let targetYear = currentYear;
let monthName = "";

// Check explicit month name in query
for (const [mName, mNum] of Object.entries(monthsMap)) {
  const regex = new RegExp('\\b' + mName + '\\b', 'i');
  if (regex.test(lower)) {
    targetMonth = mNum;
    break;
  }
}

// Check relative periods
if (lower.includes('this month') || lower.includes('bu ay') || lower.includes('current month')) {
  targetMonth = currentMonthNum;
  targetYear = currentYear;
} else if (lower.includes('last month') || lower.includes('gecen ay') || lower.includes('geçen ay') || lower.includes('previous month')) {
  if (currentMonthNum === 1) {
    targetMonth = 12;
    targetYear = currentYear - 1;
  } else {
    targetMonth = currentMonthNum - 1;
    targetYear = currentYear;
  }
} else if (lower.includes('all time') || lower.includes('overall') || lower.includes('hepsi') || lower.includes('tum zamanlar') || lower.includes('tüm zamanlar')) {
  targetMonth = 'all';
}

// If no month found, default to current month
if (!targetMonth) {
  targetMonth = currentMonthNum;
}

// Detect specific year if mentioned (e.g. 2025 or 2026)
const yearMatch = rawText.match(/\b(202[4-9])\b/);
if (yearMatch) {
  targetYear = parseInt(yearMatch[1], 10);
}

let targetPeriod = "";
if (targetMonth === 'all') {
  targetPeriod = 'all';
  monthName = 'All Time';
} else {
  const mStr = String(targetMonth).padStart(2, '0');
  targetPeriod = targetYear + '-' + mStr;
  monthName = monthNamesEn[targetMonth] + ' ' + targetYear;
}

// Detect category filter if user specifically asked about one
let categoryFilter = null;
if (/coffee|kahve|cafe/i.test(lower)) categoryFilter = 'Coffee & Snacks';
else if (/restaurant|eating out|yemek|restoran|dinner|lunch/i.test(lower)) categoryFilter = 'Dining Out & Restaurants';
else if (/grocer|market|supermarket|bakkal/i.test(lower)) categoryFilter = 'Groceries & Supermarket';
else if (/tech|computer|electronics|apple|telefon|bilgisayar|teknoloji/i.test(lower)) categoryFilter = 'Electronics & Tech';
else if (/uber|taxi|transport|taksi|ulasim|ulaşım|benzin|fuel/i.test(lower)) categoryFilter = 'Transportation & Travel';

return [{
  json: {
    ...item,
    targetPeriod,
    monthName,
    categoryFilter,
    rawQuestion: rawText,
    isTurkish: /harca|ne kadar|mart|ayında|özet|bütçe|göster/i.test(lower),
    spreadsheetId: item.config.spreadsheetId,
    sheetName: item.config.sheetName || 'Expenses'
  }
}];

// =========================================================================
// 📈 AGGREGATE MONTHLY SPENDING & CATEGORY BREAKDOWN
// =========================================================================
const allRows = $input.all().map(item => item.json);
const queryMeta = $('Parse Spending Query Target Period').first().json;
const targetPeriod = queryMeta.targetPeriod; // e.g. "2026-03" or "all"
const categoryFilter = queryMeta.categoryFilter;

// Filter rows matching target period
const matchingRows = allRows.filter(row => {
  const rowDate = String(row.Date || row.date || '');
  const rowMonth = String(row.Month || row.month || rowDate.slice(0, 7));

  const matchesPeriod = (targetPeriod === 'all') || (rowMonth === targetPeriod) || (rowDate.startsWith(targetPeriod));
  if (!matchesPeriod) return false;

  if (categoryFilter) {
    const rowCat = String(row.Category || row.category || '');
    return rowCat.toLowerCase().includes(categoryFilter.toLowerCase());
  }
  return true;
});

if (matchingRows.length === 0) {
  return [{
    json: {
      ...queryMeta,
      hasData: false,
      totalSpend: 0,
      transactionCount: 0,
      categoryBreakdown: [],
      topExpenses: [],
      briefingPrompt: "No expense records found for " + queryMeta.monthName + "."
    }
  }];
}

let grandTotal = 0;
const catTotals = {};
const catCounts = {};
const currency = matchingRows[0]?.Currency || matchingRows[0]?.currency || 'EUR';

for (const row of matchingRows) {
  const rawAmt = row.Amount || row.amount || 0;
  const amt = parseFloat(String(rawAmt).replace(/[^0-9.-]/g, '')) || 0;
  grandTotal += amt;

  const cat = String(row.Category || row.category || 'General & Miscellaneous').trim();
  catTotals[cat] = (catTotals[cat] || 0) + amt;
  catCounts[cat] = (catCounts[cat] || 0) + 1;
}

// Category icons map
const categoryIcons = {
  'Coffee & Snacks': '☕',
  'Dining Out & Restaurants': '🍽️',
  'Groceries & Supermarket': '🛒',
  'Electronics & Tech': '💻',
  'Transportation & Travel': '🚗',
  'Shopping & Clothing': '🛍️',
  'Housing & Utilities': '🏠',
  'Health & Pharmacy': '💊',
  'Entertainment & Leisure': '🎬',
  'General & Miscellaneous': '📦'
};

const categoryBreakdown = Object.keys(catTotals).map(cat => {
  const total = catTotals[cat];
  const count = catCounts[cat];
  const pct = grandTotal > 0 ? ((total / grandTotal) * 100).toFixed(1) : '0.0';
  const icon = categoryIcons[cat] || '🏷️';
  return {
    category: cat,
    icon,
    totalAmount: parseFloat(total.toFixed(2)),
    percentage: parseFloat(pct),
    count,
    avgPerTransaction: parseFloat((total / count).toFixed(2))
  };
}).sort((a, b) => b.totalAmount - a.totalAmount);

// Top 3 highest individual expenses
const topExpenses = [...matchingRows]
  .map(row => {
    const rawAmt = row.Amount || row.amount || 0;
    const amt = parseFloat(String(rawAmt).replace(/[^0-9.-]/g, '')) || 0;
    return {
      merchant: row.Merchant || row.merchant || 'Unknown',
      amount: amt,
      category: row.Category || row.category || 'General',
      date: row.Date || row.date || ''
    };
  })
  .sort((a, b) => b.amount - a.amount)
  .slice(0, 3);

// Unique dates to compute daily average
const uniqueDates = new Set(matchingRows.map(r => r.Date || r.date).filter(Boolean));
const dailyAverage = uniqueDates.size > 0 ? (grandTotal / uniqueDates.size).toFixed(2) : grandTotal.toFixed(2);

return [{
  json: {
    ...queryMeta,
    hasData: true,
    currency,
    totalSpend: parseFloat(grandTotal.toFixed(2)),
    transactionCount: matchingRows.length,
    dailyAverage: parseFloat(dailyAverage),
    activeDays: uniqueDates.size,
    categoryBreakdown,
    topExpenses
  }
}];

